function getImgList(){
    var p ="eval\\(.*\\)";
    var jseval = html.match(p)[0]; eval(eval("("+jseval.substring(5,jseval.length-1)+")"));
    var list = pages.match(/img[^\.]+\.\w{3}/g);
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        piclist[i] = "https://images.dmzj.com/" + list[i];
    }
    return piclist;
}

